record.field:
for service in records:
    if not service.x_code or not service.x_server:
        raise UserError('Fill in the service code and the server URL first.')
    url = service.x_server.rstrip('/') + '/iap_online/' + service.x_code
    if service.x_token:
        url += '?token=' + service.x_token
    send = service.x_send_action_id
    if not send:
        payload_fields = env['ir.model.fields'].search([
            ('model', '=', 'x_iap_online_request'),
            ('name', 'in', ['x_kind', 'x_input', 'x_token', 'x_callback_url', 'x_db_uuid',
                            'x_company_vat', 'x_company_name']),
        ])
        send = env['ir.actions.server'].create({
            'name': 'Terrabit: send to ' + service.x_code,
            'model_id': env.ref('deltatech_iap_online.model_x_iap_online_request').id,
            'state': 'webhook',
            'webhook_url': url,
            'webhook_field_ids': [Command.set(payload_fields.ids)],
        })
        service.write({'x_send_action_id': send.id})
    else:
        send.write({'webhook_url': url})
    env['x_iap_online_request'].create({'x_name': 'Activation', 'x_kind': 'register', 'x_service_id': service.id})
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Terrabit',
        'message': 'Activation sent. The service answers in a few seconds.',
        'type': 'info',
        'next': {'type': 'ir.actions.client', 'tag': 'soft_reload'},
    },
}

for service in records:
    env['x_iap_online_request'].create({'x_name': 'Credits', 'x_kind': 'balance', 'x_service_id': service.id})
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Terrabit',
        'message': 'Request sent: the credits are updated in a few seconds.',
        'type': 'info',
        'next': {'type': 'ir.actions.client', 'tag': 'soft_reload'},
    },
}

service = records[:1]
if not service.x_token:
    raise UserError('Activate the service first.')
action = {
    'type': 'ir.actions.act_url',
    'target': 'new',
    'url': '%s/iap/1/credit?dbuuid=%s&service_name=%s&account_token=%s' % (
        service.x_server.rstrip('/'),
        env['ir.config_parameter'].sudo().get_param('database.uuid'),
        service.x_code,
        service.x_token,
    ),
}
